'use strict';
/* Saved story campaign and neighborhood life for the photographic city. */
const cityLife=EldoriaLifeModel,cityStory=EldoriaStoryModel;
const lifeWhere=()=>({district:scene,room:cityInside,porch:cityTreehousePorch});
const lifeEsc=comfortEscape;
cityLife.ensure(state);cityStory.ensure(state);
const lifeStyle=document.createElement('link');lifeStyle.rel='stylesheet';lifeStyle.href='city-life.css?v=story-1';document.head.append(lifeStyle);
const lifeBar=document.createElement('div');lifeBar.className='city-life-bar';lifeBar.innerHTML='<button id="lifeBoard">Adventures & jobs</button><button id="lifeDaily">Today’s objectives</button><button id="lifeJournal">Story so far</button>';$('cityRoomTrail').after(lifeBar);
$('lifeBoard').onclick=()=>lifeBoard();$('lifeDaily').onclick=lifeDaily;$('lifeJournal').onclick=lifeStoryJournal;
// Put the ongoing plot above the scenery and room activities.
$('cityScene').before($('comfortObjective'));
function lifeCommit(){persist();cityDraw()}
function lifeResult(r,again){if(!r.ok){const status=$('lifeFeedback');if(status)status.textContent=r.reason||'Try another approach.';else cityMessage(r.reason||'Try again.');return false}lifeCommit();if(r.next){again?.();return true}modal(r.title||'A little progress','<p>'+lifeEsc(r.title||'Your progress is saved.')+'</p>'+(r.coins?'<p>You earned <strong>'+r.coins+' mooncoins</strong>.</p>':'')+'<p>Visit the adventure board to choose your next activity.</p>');action('Return to the city',()=>{$('modal').close();cityDraw()});return true}
function lifePhoto(room,image){const img=document.createElement('img');img.className='life-story-photo';img.alt=cityRoomNames[room]||'Story setting';img.src='assets/interiors/'+(image||comfortRoomImage(room))+'.jpg';img.onerror=()=>img.remove();$('modal').querySelector('h2').parentElement.after(img)}
function lifeTravel(station,callback){$('modal').close();if(scene!==station.district)changeScene(station.district);if(cityInside!==station.room)cityEnter(station.room);if(station.room==='owlTreehouse'&&cityTreehousePorch)cityEnterStoryRoom();if(callback)callback();else cityMessage('You have arrived. Your activity is listed below the scene.');}
comfortObjective=function(){const q=cityStory.ensure(state),m=cityStory.current(state),box=$('comfortObjective');box.classList.add('life-main-story');box.innerHTML='';const content=document.createElement('div');content.innerHTML='<span class="city-eyebrow">MAIN STORY · THE EIGHT SILVER STITCHES</span><h2>'+lifeEsc(m?m.title:'Eight names restored')+'</h2><p>'+lifeEsc(m?m.setting+' · '+(cityStory.at(state,lifeWhere())?'Your next scene is here.': 'Follow this lead to continue the family’s search.'):'The family has chosen its road home. Your life in Eldoria continues.')+'</p><progress aria-label="Story progress" max="11" value="'+q.step+'"></progress><small>'+q.step+' of 11 story objectives complete'+(q.step===7?' · '+cityStory.siblings.filter(n=>q.spoken.includes(n)).length+'/8 siblings heard':'')+'</small>';const buttons=document.createElement('div');buttons.className='life-story-buttons';const play=document.createElement('button');play.id='lifeContinueStory';play.textContent=m?(cityStory.at(state,lifeWhere())?'Play this story scene':'Follow the story →'):'Explore more adventures';play.onclick=m?lifeContinue:()=>lifeBoard();const journalButton=document.createElement('button');journalButton.textContent='Story so far';journalButton.onclick=lifeStoryJournal;buttons.append(play,journalButton);box.append(content,buttons);document.querySelectorAll('#cityMap [data-story-lead]').forEach(e=>{delete e.dataset.storyLead;e.removeAttribute('title')});if(m){const tile=document.querySelector('#cityMap button[aria-label="Travel to '+cityShort[m.district]+'"]');if(tile){tile.dataset.storyLead='true';tile.title='Next story lead: '+m.title}}};
comfortGuide=lifeContinue;$('comfortGuide').onclick=lifeContinue;$('cityRoute').onclick=lifeContinue;$('cityRoute').textContent='Follow the story';
// Keep the manuscript directly accessible alongside the playable plot.
$('cityStory').onclick=()=>comfortReadStory(0);
function lifeContinue(){const m=cityStory.current(state);if(!m){lifeBoard();return}if(!cityStory.at(state,lifeWhere()))lifeTravel(m);lifeStoryScene()}
function lifeStoryScene(){const q=cityStory.ensure(state),m=cityStory.current(state);if(!m||!cityStory.at(state,lifeWhere())){lifeContinue();return}const expected=q.step;modal(m.title,'<span class="city-eyebrow">STORY SCENE '+(expected+1)+' · '+lifeEsc(m.setting)+'</span><p class="life-dialogue">'+lifeEsc(m.text)+'</p><h3>'+lifeEsc(m.prompt)+'</h3><p id="lifeFeedback" role="status"></p>');lifePhoto(m.room,{4:'treehouse',5:'manor',6:'workshop'}[expected]);if(expected===7){cityStory.siblings.forEach((n,i)=>{const b=action((q.spoken.includes(n)?'✓ ':'')+'Hear '+n,()=>lifeSibling(n,i));b.dataset.sibling=n});}else m.choices.forEach((c,i)=>{const b=action(c,()=>{const r=cityStory.answer(state,expected,i,lifeWhere());if(!r.ok){$('lifeFeedback').textContent=r.reason;return}lifeCommit();lifeReveal(r)});b.dataset.storyChoice=i});action('Pause here · keep my progress',()=>{$('modal').close();cityDraw()})}
function lifeSibling(name,index){if(cityStory.ensure(state).step!==7||!cityStory.at(state,lifeWhere()))return;modal(name+' Silverstitch','<p class="life-dialogue">“'+lifeEsc(cityStory.voices[index])+'”</p><p id="lifeFeedback" role="status">Listen, then let this voice become part of the family’s account.</p>');action('Remember '+name+'’s words',()=>{const r=cityStory.listen(state,name,lifeWhere());if(!r.ok)return;lifeCommit();if(r.next)lifeStoryScene();else lifeReveal(r)})}
function lifeReveal(r){const q=cityStory.ensure(state);modal(r.complete?'The names given back':'A new thread revealed','<span class="city-eyebrow">'+(r.complete?'CAMPAIGN COMPLETE':'STORY PROGRESS SAVED')+'</span><p class="life-dialogue">'+lifeEsc(r.reveal)+'</p>'+(r.complete?'<p>Your family’s tradition: <strong>'+lifeEsc(q.welcome||'a welcome of their own choosing')+'</strong>. You earned 150 mooncoins and the eight silver stitches keepsake.</p>':'')+'<p>Next: '+lifeEsc(cityStory.current(state)?.title||'Make a life in the city you helped reunite.')+'</p>');action(r.complete?'Explore life in Eldoria':'Follow the next lead',r.complete?()=>{$('modal').close();lifeBoard()}:lifeContinue);action('Read the connected chapter',()=>comfortReadStory(r.chapter));action('Stay in this neighborhood',()=>{$('modal').close();cityDraw()})}
function lifeStoryJournal(){const q=cityStory.ensure(state);modal('The Eight Silver Stitches · your story','<p>A book calls eight missing siblings home. Lady Ysabet Vale’s records may explain why they disappeared. You are helping uncover the truth while the siblings decide their futures.</p><ol class="life-story-log">'+cityStory.missions.map((m,i)=>'<li class="'+(i<q.step?'complete':i===q.step?'current':'')+'"><strong>'+(i<q.step?'✓ ':i===q.step?'→ ':'')+lifeEsc(m.title)+'</strong><p>'+lifeEsc(i<q.step?m.reveal:i===q.step?m.setting:'An undiscovered thread')+'</p></li>').join('')+'</ol>');action('Continue my story',lifeContinue);action('Read the manuscript',()=>comfortReadStory(0));action('Open the evidence journal',journal)}
function lifePuzzle(id,title,submit,again){const p=cityLife.puzzle(id);if(!p)return;modal(title,'<h3>'+lifeEsc(p.title)+'</h3><p>'+lifeEsc(p.prompt)+'</p><p id="lifeSequence" aria-live="polite"></p><p id="lifeFeedback" role="status"></p>');let selected=[];p.choices.forEach((label,i)=>{const b=action(label,()=>{if(p.kind==='choice'){lifeResult(submit(i),again);return}selected.push(i);$('lifeSequence').textContent=selected.map(n=>p.choices[n]).join(' → ');if(selected.length===p.answer.length){const r=submit(selected);if(!r.ok){$('lifeFeedback').textContent=r.reason;selected=[];}else lifeResult(r,again)}});b.dataset.puzzleChoice=i});if(p.kind==='sequence')action('Clear sequence',()=>{selected=[];$('lifeSequence').textContent=''});action('Leave this activity',()=>{$('modal').close();cityDraw()})}
function lifeJob(id){const i=cityLife.jobStage(state,id);if(!i)return;if(!cityLife.place(i.job,lifeWhere())){lifeTravel(i.job,()=>lifeJob(id));return}const r=cityLife.startJob(state,id,lifeWhere());if(!r.ok){modal(i.job.name,'<p>'+lifeEsc(r.reason)+'</p>');if(cityLife.ensure(state).activeJob)action('Leave my current shift',()=>{delete state.cityLife.activeJob;lifeCommit();lifeJob(id)});return}lifeCommit();lifePuzzle(i.puzzles[i.step],i.job.name+' · task '+(i.step+1)+'/2',a=>cityLife.answerJob(state,id,a,lifeWhere()),()=>lifeJob(id))}
function lifeQuest(id){cityLife.acceptQuest(state,id);lifeCommit();const i=cityLife.questStage(state,id);if(!i||i.progress.complete)return;if(!cityLife.place(i.step,lifeWhere())){lifeTravel(i.step,()=>lifeQuest(id));return}if(i.step.requires==='owlRead'&&!state.owlStories?.includes(0)){modal(i.quest.name,'<p>First read The Elves and the Shoemaker in Aurelin’s story room.</p>');action('Open Aurelin’s bookshelf',cityOwlLibrary);return}lifePuzzle(i.step.puzzle,i.quest.name+' · '+i.step.text,a=>cityLife.answerQuest(state,id,a,lifeWhere()),()=>{modal('One step closer','<p>Your help matters. Next: '+lifeEsc(cityLife.questStage(state,id).step.text)+'</p>');action('Travel to the next task',()=>lifeQuest(id));action('Take a break',()=>{$('modal').close();cityDraw()})})}
function lifeGame(id){const i=cityLife.leisureStage(state,id);if(!i)return;if(!cityLife.place(i.game,lifeWhere())){lifeTravel(i.game,()=>lifeGame(id));return}const r=cityLife.startGame(state,id,lifeWhere());if(!r.ok){modal(i.game.name,'<p>'+lifeEsc(r.reason)+'</p>');return}lifeCommit();lifePuzzle(i.game.puzzles[i.step],i.game.name+' · round '+(i.step+1)+'/2',a=>cityLife.answerGame(state,id,a,lifeWhere()),()=>lifeGame(id))}
const lifeWords={fern:'There is always another chair. Tell me how your search is going.',cobble:'Good work gives people a steadier road home. You are learning the trade.',elian:'I have a parcel and a story for every road. I am glad yours brought you here.',pip:'A little tea, a little company. You make this street feel like home.',thistle:'Patient hands and careful notes. Those are useful in magic and in friendship.',willow:'A garden keeps its own time. Sit a moment and notice what has grown.',aurelia:'Music carries memories farther than we expect. I saved you a place by the lanterns.',aurelin:'A story is a welcome you can carry. You are welcome beneath my branches.'};
function lifeFriend(id){const p=cityLife.people.find(p=>p.id===id);if(!cityLife.place(p,lifeWhere())){lifeTravel(p,()=>lifeFriend(id));return}const points=cityLife.ensure(state).friends[id]||0;modal('A moment with '+p.name,'<p class="life-dialogue">“'+lifeEsc(lifeWords[id])+'”</p><p>Friendship: '+points+' · '+(points>=10?'Close friend':points>=4?'Friend':'Getting acquainted')+'</p><p id="lifeFeedback" role="status"></p>');action('Share a conversation',()=>{const r=cityLife.social(state,id,'talk',lifeWhere());if(!r.ok){$('lifeFeedback').textContent=r.reason;return}lifeCommit();lifeFriend(id)});action('Give one '+p.gift,()=>{const r=cityLife.social(state,id,'gift',lifeWhere());if(!r.ok){$('lifeFeedback').textContent=r.reason;return}lifeCommit();lifeFriend(id)});action('Help with a small favor',()=>lifePuzzle(p.puzzle,'A favor for '+p.name,a=>cityLife.answerFavor(state,id,a,lifeWhere())))}
function lifeDaily(){modal('Today in Eldoria · day '+cityLife.day(state),'<p>New objectives arrive each game day. Your rewards and progress are saved.</p>'+cityLife.dailyCards(state).map(c=>'<p><strong>'+lifeEsc(c.title)+'</strong> · '+Math.min(c.current,c.goal)+'/'+c.goal+' · '+c.reward+' mooncoins'+(c.claimed?' · collected':'')+'</p>').join(''));cityLife.dailyCards(state).forEach(c=>{if(!c.claimed&&c.current>=c.goal)action('Collect: '+c.title,()=>{cityLife.claimDaily(state,c.id);lifeCommit();lifeDaily()})});action('Find an adventure',()=>lifeBoard());action('Rest until tomorrow',lifeRest)}
function lifeRest(){modal('A night at your cottage','<p>Rest until morning to open new shifts, daily requests, and neighbor visits. Your quests and story leads will wait for you.</p>');action('Go home and sleep',()=>{lifeTravel({district:'home',room:'home'});state.day=cityLife.day(state)+1;state.minutes=480;lifeCommit();lifeDaily()});action('Keep exploring',()=>{$('modal').close();cityDraw()})}
function lifeHome(){if(!cityLife.place({district:'home',room:'home'},lifeWhere())){lifeTravel({district:'home',room:'home'},lifeHome);return}const l=cityLife.ensure(state);modal('Make this cottage yours','<p>Earn materials from work, then complete your own home projects.</p><p id="lifeFeedback" role="status"></p>'+cityLife.upgrades.map(u=>'<p><strong>'+(l.upgrades[u.id]?'✓ ':'')+lifeEsc(u.name)+'</strong> · '+u.coins+' coins + '+u.amount+' '+u.resource+'<br>'+lifeEsc(u.description)+'</p>').join(''));cityLife.upgrades.filter(u=>!l.upgrades[u.id]).forEach(u=>action('Build '+u.name,()=>{const r=cityLife.buyUpgrade(state,u.id,lifeWhere());if(!r.ok){$('lifeFeedback').textContent=r.reason;return}lifeCommit();lifeHome()}));action('Sleep until morning',lifeRest)}
function lifeBoard(tab='quests'){const l=cityLife.ensure(state);modal('Your life in Eldoria','<p>Follow the family’s story, find steady work, and make this kingdom your home. '+l.xp+' experience earned.</p><div id="lifeBoardTabs" class="life-tabs"></div><div id="lifeBoardContent"></div>');const tabs=$('lifeBoardTabs');for(const [id,title]of [['quests','Neighborhood quests'],['jobs','Jobs & promotions'],['leisure','Play & explore'],['friends','Friendships'],['goals','Collections & goals']]){const b=document.createElement('button');b.textContent=title;b.setAttribute('aria-pressed',String(tab===id));b.onclick=()=>lifeBoard(id);tabs.append(b)}const area=$('lifeBoardContent');function row(title,text,label,fn){const card=document.createElement('article');card.className='life-board-card';card.innerHTML='<h3>'+lifeEsc(title)+'</h3><p>'+lifeEsc(text)+'</p>';const b=document.createElement('button');b.textContent=label;b.onclick=fn;card.append(b);area.append(card)}
if(tab==='quests')cityLife.quests.forEach(q=>{const p=l.quests[q.id];row((p?.complete?'✓ ':'')+q.name,q.giver+' · '+q.reward+' mooncoins · '+(p?.complete?'Complete':q.steps[p?.step||0].text),p?.complete?'Read the outcome':p?'Continue quest':'Accept quest',()=>{if(p?.complete){modal(q.name,'<p>Your help brought this neighborhood story home. '+q.giver+' remembers what you did.</p>');return}lifeQuest(q.id)})});
if(tab==='jobs')cityLife.jobs.forEach(j=>{const i=cityLife.jobStage(state,j.id);row(j.name,j.titles[i.rank]+' · '+i.completed+' shifts · '+(j.pay+i.rank*8)+' coins + 1 '+j.resource+' per shift · '+cityShort[j.district],i.done?'Shift finished today':'Visit workplace',()=>lifeJob(j.id))});
if(tab==='leisure'){cityLife.leisure.forEach(g=>row(g.name,cityShort[g.district]+' · '+g.reward+' coins and '+g.prize,cityLife.leisureStage(state,g.id).done?'Played today':'Travel & play',()=>lifeGame(g.id)));row('A keepsake from every district',Object.keys(l.discoveries).length+'/11 discoveries. Solve the local challenge to record a memory.',l.discoveries[scene]?'Explore another district':'Discover this neighborhood',lifeDiscovery);}
if(tab==='friends')cityLife.people.forEach(p=>row(p.name,(l.friends[p.id]||0)+' friendship · '+cityShort[p.district]+' · gifts: '+p.gift,'Visit '+p.name,()=>lifeFriend(p.id)));
if(tab==='goals'){area.innerHTML='<p><strong>Job materials:</strong> '+lifeEsc(Object.entries(l.bag).map(([k,v])=>k+': '+v).join(' · ')||'Finish a shift to earn supplies.')+'</p><p><strong>Collected:</strong> '+lifeEsc(l.collection.join(', ')||'Play a leisure challenge to collect your first keepsake.')+'</p>'+cityLife.goals(state).map(g=>'<p>'+(g.complete?'✓ ':'')+lifeEsc(g.title)+' · '+Math.min(g.value,g.goal)+'/'+g.goal+'</p>').join('');row('A cottage made by you',Object.keys(l.upgrades).length+'/6 home projects completed.','Visit home projects',lifeHome)}
action('Continue the main story',lifeContinue);action('Today’s objectives',lifeDaily)}
function lifeDiscovery(){if(cityLife.ensure(state).discoveries[scene]){modal('This neighborhood is in your journal','<p>Visit another district for a new discovery.</p>');return}const district=scene;lifePuzzle(cityLife.discoveryPuzzles[district],'Discover '+cityShort[district],a=>cityLife.discover(state,district,a,lifeWhere()))}
const lifeActionsBefore=cityBuildActions;cityBuildActions=function(){lifeActionsBefore();const where=lifeWhere();if(cityStory.at(state,where)){const c=cityCard('The Eight Silver Stitches',cityStory.current(state).title,'Play story scene',lifeStoryScene,'✦');$('comfortPlaces').prepend(c)}if(cityTreehousePorch)return;cityLife.jobs.filter(j=>cityLife.place(j,where)).forEach(j=>cityCard(j.name,'Earn wages, materials and promotions through two practical tasks.','Work a shift',()=>lifeJob(j.id),'♧'));cityLife.quests.forEach(q=>{const i=cityLife.questStage(state,q.id);if(i&&!i.progress.complete&&cityLife.place(i.step,where))cityCard(q.name,i.step.text,'Continue neighborhood quest',()=>lifeQuest(q.id),'◇')});cityLife.leisure.filter(g=>cityLife.place(g,where)).forEach(g=>cityCard(g.name,'A two-round challenge with a daily reward and collectible.','Play for a keepsake',()=>lifeGame(g.id),'♫'));cityLife.people.filter(p=>cityLife.place(p,where)).forEach(p=>cityCard('Friendship with '+p.name,'Talk, help with a favor, or give a thoughtful gift.','Spend time together',()=>lifeFriend(p.id),'♡'));if(cityInside==='home')cityCard('Make a home','Build six cottage projects with materials you earn at work.','My home projects',lifeHome,'⌂');if(!cityInside&&!cityLife.ensure(state).discoveries[scene])cityCard('A neighborhood keepsake','Solve a local challenge and add this district to your exploration journal.','Discover this district',lifeDiscovery,'◇')};
const lifePeopleBefore=cityBuildPeople;cityBuildPeople=function(){lifePeopleBefore();if(cityInside==='home'){const l=cityLife.ensure(state);if(Object.keys(l.upgrades).length){const p=document.createElement('p');p.className='life-home-details';p.textContent='Made by you: '+cityLife.upgrades.filter(u=>l.upgrades[u.id]).map(u=>u.name).join(' · ');$('cityPeople').prepend(p)}}};
const lifeMapBefore=cityUpdateMap;cityUpdateMap=function(){lifeMapBefore();if($('comfortObjective'))comfortObjective()};
window.ELDORIA_LIFE={version:1,openBoard:lifeBoard,continueStory:lifeContinue};
cityDraw();persist();
